INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','easy','flashcard','What is the mechanism of action of penicillins?','["Inhibit bacterial transpeptidase (penicillin-binding proteins/PBPs), preventing cross-linking of peptidoglycan cell wall — bactericidal"]','A','Penicillins bind PBPs and block the final transpeptidation step. Without cross-linking, the cell wall weakens and bacteria lyse. Mnemonic: Penicillin Prevents Peptidoglycan cross-linking.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','easy','flashcard','Which structural feature is essential for beta-lactam antibiotics?','["The beta-lactam ring — it binds and irreversibly inhibits PBPs; hydrolysis of this ring by beta-lactamases inactivates the drug"]','A','The beta-lactam ring mimics the D-Ala-D-Ala terminus of the peptidoglycan precursor, allowing it to bind the PBP active site. Beta-lactamase production is the primary bacterial resistance mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','easy','flashcard','What is the spectrum difference between penicillin G and amoxicillin?','["Penicillin G = narrow spectrum (gram-positives); amoxicillin = broader spectrum (gram-positives + gram-negatives such as H. influenzae, E. coli, Listeria)"]','A','Amoxicillin has an amino group on the side chain that allows penetration through gram-negative outer membrane porins. It is acid-stable and well absorbed orally, unlike penicillin G.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','flashcard','Why is clavulanate combined with amoxicillin (Augmentin)?','["Clavulanate is a beta-lactamase inhibitor — it irreversibly binds beta-lactamases, protecting amoxicillin from hydrolysis and extending coverage to beta-lactamase-producing organisms"]','A','Clavulanate has a beta-lactam ring but poor antibacterial activity alone. Combined with amoxicillin it covers beta-lactamase-producing S. aureus, H. influenzae, and Moraxella. Other inhibitors: sulbactam, tazobactam, avibactam.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','flashcard','What is the approximate cross-reactivity rate between penicillins and cephalosporins?','["Approximately 1–2% (much lower than the historically cited 10%); clinically significant cross-reactivity is rare and mostly occurs with shared R1 side chains"]','A','Most penicillin-allergic patients can safely receive cephalosporins. Cross-reactivity is side-chain dependent (ampicillin/amoxicillin share side chains with cefadroxil/cephalexin). Always assess allergy severity before deciding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','flashcard','Why are all penicillins ineffective against MRSA?','["MRSA produces PBP2A (encoded by mecA gene), an altered PBP with very low affinity for all beta-lactams, so the drug cannot bind and inhibit cell wall synthesis"]','A','PBP2A maintains cell wall synthesis even at beta-lactam concentrations that saturate normal PBPs. MRSA requires vancomycin, linezolid, daptomycin, or ceftaroline (5th-gen cephalosporin with PBP2A affinity).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','flashcard','Which penicillin is used to treat MSSA infections and why?','["Nafcillin (or oxacillin/dicloxacillin) — penicillinase-resistant penicillins; bulky side chains physically block beta-lactamase access to the beta-lactam ring"]','A','Penicillinase-resistant penicillins are drugs of choice for MSSA bacteremia and endocarditis (superior to vancomycin). Dicloxacillin is used orally; nafcillin/oxacillin IV. These do NOT cover MRSA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','flashcard','What rash is associated with ampicillin use in patients with EBV (mono)?','["A diffuse maculopapular rash in ~80–100% of patients with infectious mononucleosis who receive ampicillin or amoxicillin — not a true IgE-mediated allergy, does not predict future penicillin allergy"]','A','The rash is an immune complex-mediated reaction specific to the EBV-infected state. Patients can safely receive amoxicillin after EBV infection resolves. Avoid ampicillin when EBV is clinically suspected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','hard','flashcard','What does a negative penicillin allergy skin test (penicilloyl-polylysine + minor determinants) indicate?','["Negative skin test has >97% negative predictive value — the patient is very unlikely to have an IgE-mediated hypersensitivity reaction to penicillin and can safely receive it"]','A','Most patients labeled ''penicillin-allergic'' are not truly allergic. Skin testing with major (Pre-Pen) and minor determinants can de-label patients, allowing safe penicillin use and avoiding inferior alternative antibiotics.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','hard','flashcard','Are beta-lactam antibiotics bactericidal or bacteriostatic, and is their killing time-dependent or concentration-dependent?','["Bactericidal and TIME-dependent — efficacy correlates with duration that free drug concentration remains above the MIC (% time > MIC), not peak concentration"]','A','Optimize beta-lactam dosing with frequent intervals or extended/continuous infusions to maximize %T > MIC. Contrast with aminoglycosides (concentration-dependent) and fluoroquinolones (AUC/MIC dependent).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','easy','flashcard','What is the spectrum of 1st-generation cephalosporins and a key example?','["Narrow spectrum: gram-positive cocci (MSSA, Streptococcus) and limited gram-negatives (E. coli, Klebsiella, Proteus mirabilis — PEcK). Key example: cefazolin (IV surgical prophylaxis), cephalexin (oral)"]','A','Mnemonic for gram-negatives covered by 1st gen: PEcK (Proteus mirabilis, E. coli, Klebsiella). Cefazolin is #1 for surgical prophylaxis. Not active against MRSA, Pseudomonas, or Enterococcus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','easy','flashcard','What gram-negative organisms do 2nd-generation cephalosporins add coverage for?','["Expanded gram-negative coverage including H. influenzae, Enterobacter, Neisseria, Proteus, E. coli, Klebsiella (HENPEcK mnemonic); cefoxitin/cefotetan add anaerobic coverage (B. fragilis)"]','A','Mnemonic: HENPEcK (H. influenzae, Enterobacter, Neisseria, Proteus, E. coli, Klebsiella) for 2nd gen. Cefoxitin and cefotetan useful in intra-abdominal and gynecologic infections due to anaerobic coverage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','easy','flashcard','Which 3rd-generation cephalosporin is used for bacterial meningitis and gonorrhea, and why?','["Ceftriaxone — excellent CNS penetration, once-daily dosing, covers N. meningitidis, S. pneumoniae, H. influenzae (meningitis) and N. gonorrhoeae (gonorrhea); also used for disseminated Lyme disease"]','A','Ceftriaxone is drug of choice for meningitis, gonorrhea, typhoid fever, and hospitalized CAP. Long half-life allows once-daily dosing. NOT active against Pseudomonas or MRSA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','flashcard','Which cephalosporin generation covers Pseudomonas aeruginosa and what is the key example?','["4th generation — cefepime; covers Pseudomonas plus maintains strong gram-positive and gram-negative coverage; used in febrile neutropenia and nosocomial infections"]','A','Cefepime has a zwitterionic structure allowing rapid outer membrane penetration in gram-negatives including Pseudomonas. Covers Enterobacteriaceae and MSSA. Not active against MRSA, Enterococcus, or anaerobes.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','flashcard','Which 5th-generation cephalosporin covers MRSA and how?','["Ceftaroline — binds PBP2A (the altered PBP in MRSA) in addition to standard PBPs; used for MRSA skin/soft tissue infections and community-acquired pneumonia; only beta-lactam with MRSA activity"]','A','Ceftaroline is bactericidal against MRSA and does not cover Pseudomonas. Useful when vancomycin alternatives are needed for MRSA skin infections or CAP. Approved for complicated SSTIs and CAP.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','easy','flashcard','What is the primary use of cefazolin as a cephalosporin?','["Surgical prophylaxis — covers skin flora (MSSA, Streptococcus); given within 60 minutes before incision; most commonly used prophylactic antibiotic for clean and clean-contaminated surgeries"]','A','Cefazolin''s properties make it ideal for prophylaxis: gram-positive coverage, good tissue penetration, long enough half-life (1.8 h), low cost. Re-dose every 4 hours for prolonged surgeries or after significant blood loss (>1.5 L).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','flashcard','What is the mechanism of action of carbapenems and why do they have the broadest beta-lactam spectrum?','["Inhibit PBPs like all beta-lactams but resist hydrolysis by most beta-lactamases (except carbapenemases/KPC) due to bicyclic ring structure; broadest coverage: gram-positives, gram-negatives, anaerobes, ESBL-producers"]','A','Carbapenems (imipenem, meropenem, ertapenem, doripenem) are last-resort beta-lactams for MDR organisms. They do NOT cover MRSA or Enterococcus faecium. Ertapenem does NOT cover Pseudomonas.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','flashcard','Why is imipenem always combined with cilastatin?','["Cilastatin inhibits renal dehydropeptidase-I (DHP-I), which would otherwise hydrolyze imipenem in the kidney; prevents drug inactivation and accumulation of nephrotoxic metabolites in the proximal tubule"]','A','Without cilastatin, imipenem is broken down in the proximal tubule to nephrotoxic products. Meropenem and ertapenem are stable to DHP-I and do not require cilastatin. Brand name: Primaxin (imipenem-cilastatin).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','hard','flashcard','Which carbapenem carries the highest risk of seizures and why?','["Imipenem — lowers seizure threshold more than other carbapenems due to structural similarity to GABA antagonists; risk increased in CNS lesions, renal impairment (drug accumulation); meropenem preferred for CNS infections"]','A','Use meropenem for meningitis or patients with seizure risk. Imipenem''s seizurogenic potential increases at supratherapeutic concentrations (renal dose adjustment critical). Ertapenem also has some seizure risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','hard','flashcard','For which resistant organisms is meropenem typically reserved?','["ESBL-producing Enterobacteriaceae (E. coli, Klebsiella), carbapenem-susceptible Pseudomonas, Acinetobacter, and other MDR gram-negative bacilli not responding to other beta-lactams"]','A','Meropenem is preferred over imipenem for CNS infections (lower seizure risk) and Pseudomonas. Carbapenem-resistant organisms (CRE/KPC) require colistin, polymyxin B, ceftazidime-avibactam, or cefiderocol.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','easy','flashcard','What is the mechanism of action of macrolide antibiotics?','["Bind the 50S ribosomal subunit (23S rRNA) and inhibit translocation — preventing the ribosome from moving along the mRNA; bacteriostatic (bactericidal at high concentrations)"]','A','Macrolides (erythromycin, azithromycin, clarithromycin) block translocation at the peptidyl transferase center. Mnemonic for 50S inhibitors: Our Monks Chant Loudly (Oxazolidinone, Macrolide, Chloramphenicol, cLindamycin).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','easy','flashcard','What are the main indications for azithromycin?','["Atypical community-acquired pneumonia (Mycoplasma, Chlamydophila, Legionella), chlamydia STI (single 1g dose), MAC prophylaxis in HIV, pertussis, and strep pharyngitis in penicillin allergy"]','A','Azithromycin Z-pack concentrates in tissues and macrophages (long half-life ~68 h). Minimal drug interactions compared to erythromycin. Not ideal for S. pneumoniae in areas with high macrolide resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','flashcard','What are two unique toxicities of erythromycin not shared by newer macrolides?','["QT prolongation (risk of torsades de pointes) and prokinetic GI effect (motilin receptor agonist causing nausea, vomiting, abdominal cramping); also strong CYP3A4 inhibition — numerous drug interactions"]','A','Erythromycin''s GI prokinetic effect is sometimes used therapeutically for gastroparesis. Azithromycin has minimal QT risk; clarithromycin has moderate QT risk. All macrolides inhibit CYP3A4 to varying degrees.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','flashcard','What is the role of clarithromycin in H. pylori treatment?','["Part of triple therapy for H. pylori eradication: clarithromycin + amoxicillin (or metronidazole) + PPI for 14 days; increasing clarithromycin resistance (>15% in many regions) reducing efficacy"]','A','Alternative regimens for clarithromycin-resistant H. pylori: bismuth quadruple therapy or vonoprazan-based regimens. Clarithromycin also treats MAC infections (with ethambutol ± rifabutin) in HIV patients.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','easy','flashcard','What is the mechanism of action of tetracyclines?','["Bind the 30S ribosomal subunit and block binding of aminoacyl-tRNA to the A site, preventing addition of new amino acids to the peptide chain; bacteriostatic"]','A','Tetracyclines enter bacteria via active uptake and passive diffusion. Resistance: efflux pumps and ribosomal protection proteins. Mnemonic: 30S inhibitors = Tetracyclines and Aminoglycosides (the TAGS rule).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','flashcard','List four major indications for doxycycline.','["Lyme disease (early/disseminated), Rocky Mountain Spotted Fever (RMSF), chlamydia (urogenital/PID), atypical CAP (Mycoplasma/Chlamydophila); also: malaria prophylaxis, brucellosis, cholera, anthrax post-exposure prophylaxis"]','A','Doxycycline is the preferred tetracycline: better oral absorption, twice-daily dosing, broader indications. Can be given with food (unlike tetracycline HCl). Also effective against some protozoa. Preferred over azithromycin for RMSF.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','flashcard','Why are tetracyclines contraindicated in children under 8 years old and in pregnancy?','["Chelate calcium → deposit in developing bones and teeth causing permanent yellow-brown staining, dental hypoplasia, and reversible bone growth inhibition; also teratogenic (Category D) and excreted in breast milk"]','A','Exception: doxycycline can be used in children of any age for life-threatening infections (RMSF) — risk of death outweighs cosmetic concern. Short-course doxycycline causes less staining than older tetracyclines.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','flashcard','What is the mechanism of action of chloramphenicol?','["Binds the 50S ribosomal subunit and inhibits peptidyl transferase, preventing peptide bond formation; bacteriostatic against most organisms, bactericidal against H. influenzae, N. meningitidis, S. pneumoniae"]','A','Chloramphenicol has excellent CNS penetration and broad spectrum but rarely used in high-income settings due to toxicity. In Ghana and other LMICs it may still be used for typhoid or meningitis when first-line drugs fail or are unavailable.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','hard','flashcard','What causes grey baby syndrome and when does it occur?','["Chloramphenicol toxicity in neonates — immature hepatic UDP-glucuronosyltransferase cannot conjugate chloramphenicol, causing drug accumulation → cardiovascular collapse, grey cyanosis, abdominal distension, vomiting, and death"]','A','Neonates also have reduced renal excretion. Chloramphenicol is contraindicated in neonates unless no alternatives exist and serum levels are monitored. Therapeutic range: 10–25 mg/L (peak). Toxic at >25 mg/L.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','hard','flashcard','Which life-threatening blood dyscrasia is associated with chloramphenicol and is it dose-dependent?','["Aplastic anemia (pancytopenia) — idiosyncratic, dose-INDEPENDENT reaction in ~1:25,000–40,000 patients; irreversible and often fatal; distinct from reversible dose-dependent bone marrow suppression that occurs with high serum levels"]','A','Two types of bone marrow toxicity: (1) Dose-dependent reversible suppression (common, with levels >25 mg/L); (2) Idiosyncratic aplastic anemia (rare, unpredictable, fatal). This risk drove chloramphenicol out of routine use in high-income countries.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','easy','flashcard','What is the mechanism of action of fluoroquinolones?','["Inhibit bacterial DNA gyrase (topoisomerase II) in gram-negatives and topoisomerase IV in gram-positives — preventing DNA supercoiling relief and chromosome segregation → DNA strand breaks → bactericidal"]','A','DNA gyrase introduces negative supercoils to relieve tension ahead of the replication fork. Topoisomerase IV decatenates daughter chromosomes. Fluoroquinolones trap the enzyme-DNA complex, causing double-strand breaks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','easy','flashcard','What are the main clinical uses of ciprofloxacin?','["Gram-negative UTIs/pyelonephritis, anthrax post-exposure prophylaxis and treatment, typhoid fever, uncomplicated gonorrhea, traveler''s diarrhea (Campylobacter, Salmonella, Shigella), Pseudomonas infections"]','A','Ciprofloxacin has the strongest anti-Pseudomonal activity among oral fluoroquinolones. Respiratory fluoroquinolones (levofloxacin, moxifloxacin) have better gram-positive coverage for CAP/sinusitis. Ciprofloxacin has poor S. pneumoniae coverage.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','flashcard','What is the hallmark musculoskeletal toxicity of fluoroquinolones?','["Tendinopathy and tendon rupture (most commonly Achilles tendon) — risk increased in elderly, those on corticosteroids, organ transplant recipients; can occur during or months after treatment; FDA Black Box Warning"]','A','FDA Black Box Warning for fluoroquinolones includes tendon rupture, peripheral neuropathy, and CNS effects. Avoid in children and adolescents (growing cartilage toxicity in animal studies) except for anthrax or specific serious infections where benefits outweigh risk.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','flashcard','Do fluoroquinolones cause QT prolongation?','["Yes — fluoroquinolones (especially moxifloxacin > levofloxacin > ciprofloxacin) block hERG potassium channels, prolonging the QT interval and increasing risk of torsades de pointes"]','A','Avoid fluoroquinolones with other QT-prolonging drugs (antipsychotics, amiodarone, macrolides) and in patients with congenital long QT syndrome, hypokalemia, or hypomagnesemia. Moxifloxacin has greatest QT risk and should not be used for uncomplicated UTIs.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','easy','flashcard','What is the mechanism of action of aminoglycosides?','["Bind 30S ribosomal subunit (16S rRNA) → cause misreading of mRNA → incorporation of wrong amino acids → abnormal proteins insert into membrane → increased membrane permeability → more drug uptake → bactericidal; requires oxygen for uptake — inactive against anaerobes"]','A','Aminoglycosides are INACTIVE against anaerobes and facultative anaerobes in hypoxic environments (energy-dependent uptake requires oxygen). Mnemonic: Aminoglycosides are MEAN — Misreading, Energy-dependent, Active against Negatives.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','flashcard','What are the two major dose-limiting toxicities of aminoglycosides?','["Nephrotoxicity (proximal tubular necrosis — reversible, drug accumulates in tubule cells) and ototoxicity (cochlear damage → hearing loss; vestibular damage → vertigo — often irreversible)"]','A','Risk factors: prolonged use, high doses, pre-existing renal impairment, concomitant nephrotoxins (vancomycin, NSAIDs, cisplatin), volume depletion, elderly. Monitor renal function, drug levels, and audiometry for prolonged courses.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','flashcard','Which aminoglycoside level (peak or trough) is monitored to reduce toxicity?','["Trough level (pre-dose) is monitored to minimize toxicity — elevated trough indicates drug accumulation and increased risk of nephrotoxicity and ototoxicity; peak level monitors efficacy (Peak/MIC ratio)"]','A','Extended-interval (once-daily) aminoglycoside dosing exploits concentration-dependent killing, allows the trough to fall near zero (reducing toxicity), and maintains bactericidal peak levels. Traditional dosing uses both peak and trough monitoring.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','flashcard','What is the pharmacodynamic killing pattern of aminoglycosides?','["Concentration-dependent killing — bactericidal efficacy correlates with the peak concentration to MIC ratio (Peak/MIC); higher peak concentrations = greater bacterial killing; supports once-daily extended-interval dosing"]','A','Once-daily aminoglycoside dosing achieves high peak levels for maximal kill, exploits the post-antibiotic effect (PAE), and allows trough to approach zero, reducing toxicity. Contrast with beta-lactams (time-dependent killing).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','hard','flashcard','Why is aminoglycoside + penicillin/vancomycin synergy used for Enterococcal endocarditis?','["Penicillin/vancomycin disrupts the cell wall, facilitating aminoglycoside uptake into Enterococcus (which has intrinsic low-level aminoglycoside resistance due to poor uptake); together they achieve bactericidal synergy needed for endocarditis cure"]','A','Enterococcus endocarditis cannot be treated with either drug alone — neither achieves bactericidal activity as monotherapy. High-level aminoglycoside resistance (HLAR) eliminates this synergy; alternative: ampicillin + ceftriaxone (double beta-lactam synergy).','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','hard','flashcard','When is amikacin preferred over tobramycin or gentamicin?','["Amikacin is used for gram-negative bacilli resistant to gentamicin and tobramycin — its unique structure resists most aminoglycoside-modifying enzymes (AMEs) that inactivate other aminoglycosides; reserved for MDR gram-negative infections"]','A','Amikacin is reserved for MDR gram-negative infections (e.g., MDR Pseudomonas, Acinetobacter, some ESBL producers). Tobramycin has slightly better activity against Pseudomonas; gentamicin is used for Enterococcus/Streptococcus synergy. Susceptibility testing guides selection.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','easy','flashcard','What is the mechanism of action of vancomycin?','["Binds D-Ala-D-Ala terminus of peptidoglycan precursors (lipid II) → blocks transglycosylation and transpeptidation → inhibits cell wall synthesis; bactericidal against most gram-positive organisms; cannot penetrate gram-negative outer membrane"]','A','VRE resistance: VanA/VanB genes alter the D-Ala-D-Ala target to D-Ala-D-Lac, reducing vancomycin affinity ~1000-fold. Vancomycin is a glycopeptide — too large to pass through gram-negative outer membrane porins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','easy','flashcard','What are the primary indications for vancomycin?','["MRSA infections (bacteremia, endocarditis, skin/soft tissue, pneumonia, osteomyelitis), serious gram-positive infections in penicillin-allergic patients, C. difficile colitis (oral vancomycin — non-absorbed, acts locally in colon)"]','A','IV vancomycin is NOT absorbed orally — only treats C. difficile when given PO (acts in colon). Vancomycin is NOT first-line for MSSA — nafcillin/oxacillin are superior for MSSA bacteremia and endocarditis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','flashcard','What is Red Man Syndrome and how is it prevented?','["Flushing, erythema, and pruritus over the face/neck/upper trunk during vancomycin infusion due to histamine release from mast cells (NOT IgE-mediated allergy); prevented by infusing over ≥60 minutes and premedication with antihistamines"]','A','Red Man Syndrome is rate-dependent, not a true allergy — patients can continue vancomycin with slower infusion. Distinguish from true vancomycin hypersensitivity (rare). Diphenhydramine pretreatment and slower infusion (over 2+ hours) are key management steps.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','flashcard','What vancomycin trough level is targeted for serious infections (bacteremia, endocarditis, osteomyelitis)?','["Trough target: 15–20 mg/L (or AUC/MIC 400–600 per 2020 ASHP/IDSA/SIDP guidelines); current guidelines prefer AUC-guided monitoring over trough-only to improve efficacy and minimize nephrotoxicity"]','A','AUC-guided monitoring uses Bayesian pharmacokinetic software. AUC/MIC ≥400 predicts efficacy against MRSA (MIC ≤1 mg/L). Lower troughs (10–15 mg/L) for less severe infections. Higher troughs increase nephrotoxicity risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','flashcard','What are the major toxicities of vancomycin?','["Nephrotoxicity (especially with concurrent aminoglycosides or piperacillin-tazobactam — significantly increased AKI risk), ototoxicity (rare with current monitoring), and Red Man Syndrome (rate-related infusion reaction — not a true allergy)"]','A','Risk of nephrotoxicity is significantly increased when vancomycin is combined with piperacillin-tazobactam (higher AKI rates vs. vancomycin + cefepime in multiple studies). This combination should be used with caution and close monitoring of renal function.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','flashcard','What is the mechanism of action of daptomycin?','["Inserts into gram-positive bacterial cell membrane in a Ca2+-dependent manner → forms oligomeric channels → rapid membrane depolarization → loss of membrane potential → cessation of DNA, RNA, and protein synthesis → rapid bactericidal death"]','A','Daptomycin is a cyclic lipopeptide with unique membrane-disrupting mechanism. Active against MRSA, VRE, and other resistant gram-positives. Myopathy (CPK elevation) is main adverse effect — monitor CPK weekly. Not for pneumonia.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','hard','flashcard','Why can daptomycin NOT be used to treat pneumonia?','["Pulmonary surfactant (phosphatidylglycerol) binds and inactivates daptomycin in the alveoli, rendering it ineffective for pulmonary infections — use linezolid or vancomycin for MRSA pneumonia instead"]','A','Daptomycin''s lipid tail inserts into surfactant lipid bilayers rather than bacterial membranes in the lung, neutralizing its activity. Use daptomycin for bacteremia, endocarditis, complicated SSTIs — never for pneumonia.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','flashcard','What is the mechanism of action of linezolid?','["Binds the 23S rRNA of the 50S ribosomal subunit → prevents formation of the 70S initiation complex → inhibits translation initiation; bacteriostatic against gram-positive organisms; oral bioavailability ~100% (ideal IV-to-PO switch)"]','A','Linezolid''s unique mechanism (initiation complex inhibition) means no cross-resistance with other 50S inhibitors. Active against MRSA, VRE, and linezolid-susceptible MDR-TB. Bactericidal against S. pneumoniae.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','hard','flashcard','What is the risk of combining linezolid with SSRIs or serotonergic agents?','["Serotonin syndrome — linezolid is a weak MAO inhibitor; combined with SSRIs, SNRIs, TCAs, or meperidine it can cause serotonin excess: agitation, hyperthermia, clonus, autonomic instability; potentially life-threatening"]','A','If linezolid is urgently needed, consider discontinuing serotonergic agents ≥2 weeks before (5 half-lives for fluoxetine). Also avoid sympathomimetics (hypertensive crisis). Linezolid''s MAO inhibition is reversible and relatively weak but clinically significant.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','hard','flashcard','What hematologic toxicity is associated with long-term linezolid use?','["Myelosuppression — especially thrombocytopenia (most common), but also anemia and neutropenia; occurs with prolonged use (>2 weeks); mechanism is mitochondrial protein synthesis inhibition in hematopoietic stem cells"]','A','Monitor CBC weekly for patients on linezolid >2 weeks. Thrombocytopenia typically resolves after stopping linezolid. Long-term use also risks lactic acidosis (mitochondrial ribosomes inhibited). Tedizolid (next-generation oxazolidinone) has less myelosuppressive potential.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','easy','flashcard','What is the mechanism of action of amphotericin B?','["Binds ergosterol in the fungal cell membrane → forms transmembrane pores → increased membrane permeability → leakage of ions (K+, Mg2+) and cellular contents → fungal cell death; fungicidal with broadest antifungal spectrum"]','A','Amphotericin B binds ergosterol with high affinity (also binds cholesterol in human cells with lower affinity — basis of toxicity). Resistance is rare. Covers Candida, Aspergillus, Cryptococcus, Mucor, Histoplasma, Coccidioides.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','flashcard','What are the major toxicities of amphotericin B and how are they minimized?','["Nephrotoxicity (dose-limiting — azotemia, hypokalemia, hypomagnesemia, renal tubular acidosis) and infusion reactions (fever, rigors, hypotension); minimized by NS pre-hydration and lipid formulations (AmBisome = liposomal amphotericin B)"]','A','Liposomal amphotericin B (AmBisome) has significantly less nephrotoxicity (liposomes preferentially deliver drug to fungal cells) and fewer infusion reactions. Pre-medicate with antipyretics, antihistamines, meperidine (for rigors). Also causes anemia (EPO suppression).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','easy','flashcard','What is the mechanism of action of azole antifungals?','["Inhibit fungal cytochrome P450 enzyme lanosterol 14α-demethylase (CYP51) → block conversion of lanosterol to ergosterol → depletion of ergosterol + accumulation of toxic methylated sterols → impaired membrane function; generally fungistatic"]','A','Azoles (fluconazole, itraconazole, voriconazole, posaconazole, isavuconazole) also inhibit human CYP enzymes to varying degrees → numerous drug-drug interactions. Voriconazole and itraconazole are potent CYP3A4 inhibitors.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','flashcard','What are the primary indications for fluconazole?','["Vulvovaginal candidiasis (single 150mg dose), oropharyngeal/esophageal candidiasis, candidemia step-down from echinocandin in stable patients, Cryptococcal meningitis maintenance therapy (consolidation/maintenance phases after induction)"]','A','Fluconazole does NOT cover Aspergillus or Candida krusei (intrinsically resistant). Variable activity against C. glabrata. Excellent oral bioavailability and CSF penetration make it valuable for Cryptococcal meningitis maintenance therapy.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','flashcard','Which antifungal is first-line for invasive Aspergillosis?','["Voriconazole — a triazole with excellent activity against Aspergillus spp.; superior to amphotericin B in clinical trials for invasive pulmonary aspergillosis; also covers Fusarium and some other molds"]','A','Voriconazole unique toxicities: visual disturbances (photopsia — transient altered visual perception, ~30% of patients), hepatotoxicity, photosensitivity/skin squamous cell carcinoma with long-term use, hallucinations. Monitor levels (non-linear PK). Isavuconazole is an alternative.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','flashcard','What is the mechanism of action of echinocandins?','["Non-competitively inhibit beta-1,3-D-glucan synthase (FKS gene product) → block synthesis of beta-glucan (essential fungal cell wall polysaccharide) → cell wall disruption → fungal cell lysis; fungicidal against Candida, fungistatic against Aspergillus"]','A','Echinocandins (caspofungin, micafungin, anidulafungin): excellent safety profile, minimal drug interactions, no dose adjustment for renal impairment. First-line for invasive Candidiasis/Candidemia (especially in critically ill or azole-resistant patients).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','hard','flashcard','Why are echinocandins ineffective against Cryptococcus neoformans?','["Cryptococcus lacks significant beta-1,3-D-glucan in its cell wall — it has a thick polysaccharide capsule (glucuronoxylomannan) instead; without the echinocandin target, the drug has no activity"]','A','Cryptococcal treatment: induction with amphotericin B + flucytosine for 2 weeks, then fluconazole consolidation x 8 weeks, then fluconazole maintenance. Echinocandins have NO role in Cryptococcal infections.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','hard','flashcard','Why is flucytosine (5-FC) always used in combination rather than alone?','["Rapid resistance emerges with monotherapy (spontaneous mutation rate ~1:10^6 fungal cells); used in combination with amphotericin B for Cryptococcal meningitis induction — synergistic fungicidal activity and delays resistance"]','A','5-FC mechanism: taken up by fungal cytosine permease → converted to 5-FU → inhibits thymidylate synthase (DNA synthesis) + incorporated into fungal RNA. Bone marrow suppression and hepatotoxicity are dose-dependent toxicities; monitor CBC and LFTs.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','flashcard','What is the mechanism of action of terbinafine and what infections is it used for?','["Inhibits fungal squalene epoxidase (earlier in ergosterol synthesis pathway than azoles) → squalene accumulates (toxic) + ergosterol depleted → membrane disruption; fungicidal against dermatophytes; used for onychomycosis, tinea pedis/corporis/cruris"]','A','Terbinafine is drug of choice for onychomycosis (nail fungus) — more effective than azoles with shorter treatment course. Oral terbinafine: hepatotoxic (monitor LFTs), rare taste disturbance. Topical terbinafine for superficial tinea infections.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','hard','flashcard','How do azole antifungals cause clinically significant drug interactions?','["Azoles inhibit CYP3A4 (and other CYPs) → increase plasma concentrations of CYP3A4 substrates: statins (myopathy), cyclosporine (nephrotoxicity), warfarin (bleeding — CYP2C9), sirolimus, tacrolimus, benzodiazepines, many antiretrovirals"]','A','Interaction severity: voriconazole/itraconazole (strong CYP3A4 inhibitors) > fluconazole (moderate CYP3A4, strong CYP2C9 inhibitor) > isavuconazole. Some combinations contraindicated (e.g., voriconazole + rifampin reduces voriconazole levels by 96%). Always check interactions before prescribing azoles.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','easy','flashcard','What is the mechanism of action of NRTIs?','["Structural nucleoside/nucleotide analogues lacking a 3-OH group; after intracellular phosphorylation to active triphosphate form, compete with natural dNTPs for incorporation into viral DNA by reverse transcriptase → chain termination"]','A','NRTIs: TDF/TAF (tenofovir), FTC (emtricitabine), 3TC (lamivudine), ABC (abacavir), AZT (zidovudine). All require intracellular phosphorylation. NtRTIs (tenofovir) are nucleotides requiring only 2 phosphorylation steps vs. 3 for NRTIs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','easy','flashcard','How do NNRTIs differ mechanistically from NRTIs?','["NNRTIs bind a hydrophobic pocket adjacent to (not at) the RT active site (allosteric/non-competitive inhibition) → conformational change → reduced RT catalytic activity; do NOT require phosphorylation; do NOT cause chain termination"]','A','NNRTIs: efavirenz, nevirapine, rilpivirine, etravirine, doravirine. All metabolized by CYP450. Single mutations in RT (K103N for efavirenz/nevirapine; E138K for rilpivirine) confer resistance — low genetic barrier (except etravirine).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','flashcard','What CNS adverse effects are characteristic of efavirenz?','["Vivid dreams/nightmares, insomnia, dizziness, confusion, impaired concentration, depression, and rarely psychosis — occur in up to 50% of patients; typically improve after 2–4 weeks; take at bedtime to reduce CNS effects"]','A','Efavirenz is teratogenic (neural tube defects in primate studies — Category D); avoid in first trimester. It is a CYP3A4 inducer (reduces levels of protease inhibitors, statins, hormonal contraceptives). Widely used in Africa in NNRTI-based first-line ART programs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','flashcard','What is the mechanism of action of HIV protease inhibitors (PIs)?','["Inhibit HIV-1 protease, the enzyme that cleaves the Gag-Pol polyprotein precursor into functional structural proteins and enzymes; without cleavage, virions are assembled but immature and non-infectious"]','A','PIs: ritonavir, lopinavir, atazanavir, darunavir, saquinavir. Darunavir is the preferred PI (boosted with ritonavir or cobicistat). All PIs are CYP3A4 substrates; low-dose ritonavir used as pharmacokinetic booster (potent CYP3A4 inhibitor) to increase levels of co-administered PIs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','flashcard','What is the class-wide metabolic toxicity of protease inhibitors?','["Lipodystrophy syndrome: peripheral fat wasting (lipoatrophy — face, limbs) + central fat accumulation (visceral adiposity, buffalo hump), dyslipidemia (elevated TG/LDL), insulin resistance/hyperglycemia, and increased cardiovascular risk"]','A','Metabolic syndrome with PIs occurs via inhibition of adipocyte differentiation, GLUT-4 expression, and lipid metabolism. Atazanavir has least lipid effect. PIs are potent CYP3A4 inhibitors → extensive drug interactions. Also cause nephrolithiasis (atazanavir, indinavir).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','flashcard','What is the mechanism of action of integrase strand transfer inhibitors (INSTIs)?','["Bind Mg2+ cofactors in the HIV integrase active site → chelate the integrase-viral DNA complex → prevent strand transfer step (insertion of viral DNA into host chromosome) → no provirus formation"]','A','INSTIs: raltegravir, elvitegravir, dolutegravir (DTG), bictegravir, cabotegravir. DTG and bictegravir have high barrier to resistance (two mutations required). INSTIs are now the preferred third agent in all first-line ART regimens per WHO/DHHS guidelines.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','easy','flashcard','What is the preferred first-line ART regimen in treatment-naive adults?','["Two NRTIs (tenofovir/emtricitabine = TDF/FTC or TAF/FTC) + one INSTI (dolutegravir = DTG); co-formulated as single-tablet regimens (e.g., Biktarvy: bictegravir/TAF/FTC; Triumeq: ABC/3TC/DTG)"]','A','WHO and DHHS recommend DTG-based regimens as preferred: high potency, high barrier to resistance, few side effects, minimal drug interactions, once-daily dosing, low pill burden, available as affordable generic in LMICs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','hard','flashcard','What pre-treatment test is mandatory before prescribing abacavir, and why?','["HLA-B*5701 screening — carriers of this allele have 55–60% risk of severe hypersensitivity reaction (fever, rash, GI symptoms, respiratory distress) that can be fatal on re-challenge; abacavir absolutely contraindicated if HLA-B*5701 positive"]','A','Abacavir hypersensitivity is immune-mediated, specific to HLA-B*5701 carriers. Reaction typically occurs in first 6 weeks. If the test is negative, risk of hypersensitivity is very low (<1%). Pharmacogenomic testing routinely done before any ABC-containing regimen.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','hard','flashcard','What are the advantages of dolutegravir (DTG) that make it the preferred first-line INSTI?','["High barrier to resistance (requires 2+ mutations), once-daily dosing, minimal drug interactions (not a significant CYP3A4 inhibitor/substrate), well tolerated, effective across all viral loads, suitable in pregnancy after first trimester, and available as affordable generic in LMICs"]','A','Potential concern: slightly increased neural tube defect risk (~0.1%) with DTG at conception — counsel women of childbearing potential. WHO now recommends DTG for all including pregnant women (benefit > risk). DTG raises serum creatinine slightly (inhibits tubular secretion) — not true GFR reduction.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','hard','flashcard','What is the mechanism of action of maraviroc and what test is required before use?','["CCR5 antagonist — binds human CCR5 co-receptor (not viral protein), causing conformational change that prevents gp120 binding and viral entry; REQUIRES tropism testing (Trofile assay) to confirm CCR5-tropic (R5) virus — ineffective against CXCR4-tropic (X4) or dual/mixed-tropic HIV"]','A','~50–60% of treatment-naive patients have CCR5-tropic virus. Maraviroc is used in treatment-experienced patients with CCR5-tropic HIV resistant to other antiretrovirals. As the only entry inhibitor targeting a host protein, it has a unique resistance profile. Monitor LFTs.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','easy','flashcard','What is the mechanism of action of acyclovir?','["Viral thymidine kinase (TK) preferentially phosphorylates acyclovir to monophosphate → cellular kinases complete phosphorylation to triphosphate → incorporated into viral DNA by viral DNA polymerase → chain termination (lacks 3-OH) + irreversible polymerase inhibition"]','A','Selectivity: viral TK phosphorylates acyclovir efficiently while human TK does not; acyclovir-TP has much higher affinity for viral vs. human DNA polymerase. Active against HSV-1, HSV-2, VZV. Minimal activity against CMV (CMV lacks TK).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','easy','flashcard','What is the difference between acyclovir and valacyclovir?','["Valacyclovir is an L-valyl ester prodrug of acyclovir — converted to acyclovir by intestinal/hepatic valacyclovir hydrolase after oral absorption; bioavailability ~54% vs acyclovir''s 15–30%, achieving plasma levels similar to IV acyclovir with less frequent dosing"]','A','Valacyclovir provides plasma acyclovir levels equivalent to IV acyclovir when taken orally, making it preferred for most outpatient HSV/VZV indications. Famciclovir is a prodrug of penciclovir (similar mechanism/spectrum). All three used for genital herpes, zoster, cold sores.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','flashcard','What are the main clinical indications for acyclovir/valacyclovir?','["HSV-1/HSV-2 (primary genital herpes, recurrences, suppressive therapy, herpes labialis, neonatal HSV), Varicella-Zoster Virus (chickenpox in immunocompromised, herpes zoster/shingles), HSV encephalitis (IV acyclovir 10 mg/kg q8h x 14–21 days)"]','A','Nephrotoxicity (crystal nephropathy) is the main IV acyclovir toxicity — ensure adequate hydration. Neurological side effects (confusion, tremor) at high doses or with renal impairment. Not adequate for CMV (use ganciclovir/valganciclovir).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','flashcard','Why is ganciclovir used for CMV instead of acyclovir, and what is its major toxicity?','["CMV lacks thymidine kinase, so acyclovir cannot be activated; ganciclovir is phosphorylated by CMV-encoded UL97 kinase → active against CMV; major toxicity is myelosuppression (neutropenia, thrombocytopenia) — more severe than acyclovir''s nephrotoxicity"]','A','Ganciclovir/valganciclovir (prodrug, ~60% oral bioavailability) indications: CMV retinitis, colitis, pneumonitis (in transplant/HIV), CMV prophylaxis in transplant recipients. Also more active than acyclovir against EBV and HHV-8.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','hard','flashcard','When is foscarnet used and what is its mechanism of action?','["Foscarnet (phosphonoformic acid) is a pyrophosphate analogue that directly inhibits viral DNA polymerase (and HIV RT) at the pyrophosphate binding site — does NOT require phosphorylation (no viral TK needed); used for acyclovir-resistant HSV/VZV and ganciclovir-resistant CMV"]','A','Foscarnet is nephrotoxic (electrolyte wasting — hypocalcemia, hypomagnesemia, hypophosphatemia) and can cause seizures. Must be given with aggressive saline hydration. Penile/vulvar ulcers reported. Reserved for resistant infections due to toxicity.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','easy','flashcard','What is the mechanism of action of oseltamivir (Tamiflu)?','["Competitive inhibitor of influenza neuraminidase (sialidase) — prevents cleavage of sialic acid linkages on host cell surface → newly formed virions remain trapped (agglutinated), unable to spread to new cells; active against influenza A and B"]','A','Neuraminidase cleaves the bond between hemagglutinin and sialic acid on host cells, releasing new virions. Oseltamivir blocks this → virion clumping. Reduces symptom duration by ~1 day if started early. Resistance: H275Y mutation in H1N1.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','flashcard','Within what time window must oseltamivir be initiated for maximum benefit?','["Within 48 hours of symptom onset — greatest benefit when started early; reduces duration and severity; still recommended beyond 48 hours in hospitalized patients, immunocompromised, or severe disease regardless of timing"]','A','Oseltamivir recommended for high-risk groups (elderly, young children, pregnant women, immunocompromised, severe illness) even after 48 hours. Dose: 75 mg twice daily x 5 days (treatment); 75 mg once daily x 10 days (post-exposure prophylaxis). Zanamivir (inhaled) is an alternative.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','hard','flashcard','Why is ribavirin classified as Pregnancy Category X (teratogenic)?','["Ribavirin causes dose-dependent teratogenicity and embryolethality in all animal species tested — causes limb, craniofacial, and cardiac defects; two forms of contraception required during therapy and for 6 months after discontinuation for both patient AND male partner"]','A','Ribavirin MOA: guanosine analogue → inhibits inosine monophosphate dehydrogenase (IMPDH) → depletes GTP → inhibits viral RNA capping and polymerase; also causes RNA mutagenesis. Previously used for HCV (with PEG-interferon); now largely replaced by DAAs. Also used for RSV, Hantavirus, Lassa fever.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','hard','flashcard','What is the mechanism of action of sofosbuvir for HCV?','["Sofosbuvir is a nucleotide analogue (NS5B polymerase inhibitor) — prodrug metabolized to uridine triphosphate analogue → incorporated by HCV NS5B RNA-dependent RNA polymerase → chain termination; pan-genotypic activity (all HCV genotypes 1–6)"]','A','Sofosbuvir is a Direct-Acting Antiviral (DAA) used in combination: sofosbuvir/ledipasvir (Harvoni), sofosbuvir/velpatasvir (Epclusa), sofosbuvir/velpatasvir/voxilaprevir (Vosevi). SVR rates >95% in 8–12 weeks. WHO essential medicines list inclusion expanding access in LMICs.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','flashcard','Which antivirals are used for chronic Hepatitis B (HBV) and what is their mechanism?','["Tenofovir (TDF or TAF) and entecavir — nucleoside/nucleotide RT inhibitors that inhibit HBV DNA polymerase (which has RT activity), causing chain termination and suppression of viral replication; do not eradicate cccDNA but suppress HBV DNA long-term"]','A','Entecavir: high barrier to resistance, minimal drug interactions, not active against HIV. Tenofovir: also first-line for HIV co-infection (covers both viruses). Lamivudine/adefovir avoided (high resistance rates). Goal: suppress HBV DNA to undetectable, normalize ALT, reduce cirrhosis/HCC risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','easy','flashcard','What is the mechanism of action of chloroquine against Plasmodium?','["Accumulates in parasite food vacuole → inhibits heme polymerase (prevents conversion of toxic free heme to inert hemozoin/malaria pigment) → toxic heme accumulates → parasite membrane damage → parasite death"]','A','Parasites digest host RBC hemoglobin, releasing heme. Normally they polymerize heme into insoluble hemozoin. Chloroquine raises vacuolar pH and directly inhibits heme polymerization, causing heme toxicity to the parasite. Also intercalates DNA.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','easy','flashcard','Which Plasmodium species remain susceptible to chloroquine?','["P. vivax (most strains), P. ovale, and P. malariae — chloroquine remains effective for these species in most geographic areas; P. falciparum is widely resistant (except some Caribbean/Central American areas)"]','A','P. vivax chloroquine resistance has emerged in Papua New Guinea, Indonesia, and parts of South America. For P. vivax outside these areas, chloroquine + primaquine (to eliminate hypnozoites) is standard. P. knowlesi: chloroquine or ACT.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','flashcard','What is the mechanism of chloroquine resistance in P. falciparum?','["Mutation in P. falciparum chloroquine resistance transporter gene (pfcrt K76T mutation) → PfCRT protein pumps chloroquine out of the food vacuole before it can inhibit heme polymerization; pfmdr1 mutations provide additional resistance"]','A','The pfcrt K76T mutation is present in nearly all chloroquine-resistant strains globally. This resistance pattern is why artemisinin-based combination therapies (ACTs) replaced chloroquine for P. falciparum worldwide, including in Ghana.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','flashcard','What is the mechanism of action of artemisinin derivatives?','["Endoperoxide bridge reacts with intraparasitic iron (heme-Fe2+) → generates reactive oxygen species (carbon-centered and oxygen-centered free radicals) → alkylate/damage parasite proteins and membranes → rapid killing of ring-stage and early trophozoite parasites"]','A','Artemisinins (artemether, artesunate, dihydroartemisinin) have the fastest parasite clearance of all antimalarials (reduce parasitemia ~10,000-fold per cycle). Short half-life (1–2 h) necessitates combination with a longer-acting partner drug (ACT) to prevent recrudescence. Artemisinin partial resistance: kelch13 mutations.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','easy','flashcard','According to Ghana STG 2017, what is the first-line treatment for uncomplicated malaria?','["Artemether-Lumefantrine (AL/Coartem) — an artemisinin-based combination therapy (ACT); standard adult dose: 4 tablets (20 mg artemether/120 mg lumefantrine) twice daily for 3 days (6 doses total); take with food or full-fat milk to enhance lumefantrine absorption"]','A','Ghana STG 2017 designates artemether-lumefantrine as first-line for uncomplicated P. falciparum malaria in all age groups. Lumefantrine is a long-acting arylaminoalcohol that eliminates residual parasites after rapid-acting artemether clears most parasitemia. The combination prevents resistance emergence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','easy','flashcard','According to Ghana STG 2017, what is the treatment for severe malaria?','["Artesunate IV (intravenous) — 2.4 mg/kg IV at 0, 12, and 24 hours, then daily until patient can tolerate oral therapy; switch to oral ACT (artemether-lumefantrine) to complete 3-day course once tolerating oral intake; superior to quinine IV per AQUAMAT/SEAQUAMAT trials"]','A','Ghana STG 2017 and WHO guidelines designate artesunate IV as first-line for severe malaria, replacing IV quinine. Artesunate is water-soluble (unlike artemether), allowing IV administration and rapid brain penetration. Monitor blood glucose (hypoglycemia risk) and for post-artesunate delayed hemolysis (PADH) 1–4 weeks later.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','flashcard','What is the role of primaquine in malaria treatment and why is it needed?','["Primaquine eliminates dormant liver-stage hypnozoites of P. vivax and P. ovale — prevents relapse; also has gametocytocidal activity against P. falciparum (reduces transmission); NOT active against blood-stage schizonts; used as radical cure after chloroquine for vivax/ovale malaria"]','A','P. vivax and P. ovale form hypnozoites in hepatocytes that can reactivate weeks to years later (relapse, not reinfection). Primaquine MOA: oxidative stress via metabolites → mitochondrial damage in hypnozoites. Tafenoquine (newer 8-aminoquinoline) has longer half-life — single dose radical cure alternative.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','flashcard','Why must G6PD status be checked before prescribing primaquine?','["Primaquine oxidizes glutathione in RBCs; G6PD-deficient patients cannot regenerate NADPH (needed to reduce oxidized glutathione) → oxidative hemolytic anemia with potentially severe/fatal hemolysis — severity depends on G6PD variant"]','A','G6PD deficiency is the most common enzymatic disorder in humans (~400 million affected), with highest prevalence in malaria-endemic regions (Africa, Mediterranean, Middle East, Asia) — an evolutionary adaptation against P. falciparum. If deficient, use chloroquine weekly x 8 weeks (alternative) or supervised primaquine with monitoring.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','hard','flashcard','What is cinchonism and which antimalarial causes it?','["Cinchonism = quinine toxicity syndrome: tinnitus, hearing loss, visual disturbances (blurred vision, altered color vision), headache, nausea, vertigo — occurs at therapeutic and slightly supratherapeutic quinine levels; reversible on dose reduction"]','A','Quinine also causes hypoglycemia (stimulates insulin secretion — especially dangerous in pregnancy), QT prolongation/cardiac arrhythmias, and thrombocytopenia. Quinidine (its stereoisomer) is used for severe malaria when IV artesunate is unavailable. Quinine remains second-line for uncomplicated malaria (with doxycycline or clindamycin).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','hard','flashcard','What neuropsychiatric adverse effects are associated with mefloquine and in whom is it contraindicated?','["Anxiety, vivid nightmares, psychosis, hallucinations, depression, and seizures — occur in 1:10,000–1:13,000 at prophylactic doses but more common at treatment doses; contraindicated in patients with psychiatric disorders, seizure history, or prior mefloquine neuropsychiatric effects"]','A','Mefloquine''s neuropsychiatric effects are due to CNS accumulation and antagonism of adenosine receptors and GABA-A receptors. Very long half-life (~3 weeks) — effects may persist. Also causes QT prolongation. Used as weekly prophylaxis in appropriate patients.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed')
,('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','easy','flashcard','What is the mechanism of action of metronidazole?','["Enters anaerobic/microaerophilic organisms; electron transport proteins reduce the nitro group → reactive nitro radical anion intermediate → causes single- and double-strand DNA breaks → cell death; bactericidal/antiprotozoal; INACTIVE in aerobic conditions"]','A','Metronidazole is selectively toxic because anaerobes and microaerophiles have the low intracellular redox potential needed to reduce the nitro group. Aerobic organisms and mammalian cells cannot activate it. Mnemonic: Metro takes the anaerobic subway.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','easy','flashcard','What drug interaction must patients be warned about when taking metronidazole?','["Disulfiram-like reaction with alcohol — metronidazole inhibits acetaldehyde dehydrogenase → acetaldehyde accumulates → flushing, tachycardia, nausea, vomiting, headache, hypotension; avoid alcohol during treatment and for 48 hours after last dose"]','A','Tinidazole (related nitroimidazole, longer half-life, fewer GI side effects) has the same alcohol interaction. Metronidazole also inhibits CYP2C9 → increases warfarin levels. Metallic taste is a common minor side effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','flashcard','What are the major clinical indications for metronidazole?','["Protozoal: amoebiasis (E. histolytica), giardiasis (G. lamblia), trichomoniasis (T. vaginalis — treat sexual partners concurrently); Bacterial: bacterial vaginosis (BV), C. difficile colitis (oral), H. pylori triple therapy, intra-abdominal anaerobic infections"]','A','Metronidazole is drug of choice for: Giardia, Trichomonas, intestinal amoebiasis (+ diloxanide furoate to eliminate luminal cysts), BV, and anaerobic infections. For C. difficile, fidaxomicin > oral vancomycin > metronidazole (metronidazole for mild CDI if others unavailable).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','flashcard','What is the mechanism of action of albendazole?','["Binds beta-tubulin → inhibits tubulin polymerization → disrupts microtubule formation → impairs glucose uptake, nutrient absorption, and secretory vesicle transport in helminths → worm immobilization and death; also inhibits fumarate reductase"]','A','Albendazole has broad anthelmintic spectrum: nematodes (roundworm, hookworm, whipworm, pinworm, strongyloides, toxocara), some cestodes (Echinococcus/hydatid disease, neurocysticercosis). Take with fatty meal to enhance absorption (poor baseline bioavailability).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','easy','flashcard','What is the mechanism of action of praziquantel?','["Increases permeability of the helminth tegument to calcium ions → massive Ca2+ influx → spastic paralysis of worm musculature → worm dislodges from vessel/tissue walls → destroyed by host immune system; also causes vacuolization and disruption of the tegument"]','A','Praziquantel is drug of choice for most trematodes and cestodes. Works within hours — rapid onset. Well tolerated; transient GI side effects common. Not effective against newly excysted metacercariae or eggs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','flashcard','List the major indications for praziquantel.','["Schistosomiasis (all species — drug of choice), intestinal tapeworms (Taenia saginata, T. solium, Diphyllobothrium, Hymenolepis), liver/lung flukes (Clonorchis, Opisthorchis, Paragonimus), neurocysticercosis (T. solium — with albendazole and corticosteroids)"]','A','For neurocysticercosis: praziquantel + albendazole + corticosteroids (dexamethasone) + anti-epileptics; steroids prevent inflammatory reaction to dying cysts. NOT used for Echinococcus (hydatid disease) — use albendazole; cyst rupture with praziquantel is dangerous.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','flashcard','What is the mechanism of action of ivermectin?','["Binds glutamate-gated chloride channels (GluCl channels) in invertebrate nerve/muscle cells → irreversible opening → Cl- influx → hyperpolarization → flaccid paralysis of pharyngeal muscles and body wall → worm death/immobilization; also potentiates GABA-gated Cl- channels"]','A','GluCl channels are unique to invertebrates (nematodes, insects, arthropods) — absent in mammals (explaining selective toxicity). Ivermectin does not cross the human blood-brain barrier at therapeutic doses. Also disrupts microfilaria membrane. Risk of CNS toxicity with mdr1 (ABCB1) gene mutations.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','flashcard','What are the main clinical indications for ivermectin?','["Onchocerciasis (river blindness — kills microfilariae, reduces transmission; annual mass drug administration), Strongyloidiasis (drug of choice), Scabies (oral for crusted/Norwegian scabies — 200 mcg/kg; also topical), lymphatic filariasis (with albendazole/DEC)"]','A','Ivermectin causes Mazzotti-like reaction in onchocerciasis (fever, pruritus, rash, myalgia from dying microfilariae) — less severe than DEC''s Mazzotti reaction. WHO essential medicine for onchocerciasis and lymphatic filariasis elimination programs (Mectizan Donation Program by Merck).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','hard','flashcard','What is the key limitation of ivermectin in treating onchocerciasis?','["Ivermectin kills only microfilariae (larval stage) and does NOT kill adult Onchocerca volvulus worms (no macrofilaricidal activity); adult worms survive (lifespan 10–15 years) and continue producing microfilariae — requires annual retreatment"]','A','Moxidectin (similar MOA) has more sustained microfilarial suppression (single dose suppresses for ~18 months vs. ivermectin''s 6 months). True macrofilaricidal treatment: doxycycline kills Wolbachia endosymbiont → adult worm sterilization/death over months of treatment.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','hard','flashcard','What is the role of diethylcarbamazine (DEC) in treating lymphatic filariasis?','["DEC is drug of choice for lymphatic filariasis (Wuchereria bancrofti, Brugia malayi, B. timori) — kills both microfilariae and adult worms; MOA: alters microfilarial surface, enhancing host immune-mediated killing; also has direct toxic effect on microfilariae"]','A','DEC + albendazole (in non-onchocerciasis/loiasis areas) is WHO-recommended MDA regimen for lymphatic filariasis elimination. DEC causes Mazzotti reaction (fever, pruritus, rash, hypotension from dying microfilariae). Avoid DEC in areas co-endemic with Loa loa (risk of fatal encephalopathy) — use ivermectin + albendazole instead.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
